import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

const GATE_SCRIPT = resolve('scripts/enforce-quality.sh');

function makeRepo() {
  const dir = mkdtempSync(join(tmpdir(), 'quality-gate-'));
  const git = (...args) => execFileSync('git', args, { cwd: dir, stdio: 'pipe' });
  git('init', '--quiet');
  git('config', 'user.email', 'test@example.com');
  git('config', 'user.name', 'Test');
  writeFileSync(join(dir, 'README.md'), 'seed\n');
  git('add', 'README.md');
  git('commit', '--quiet', '-m', 'seed');
  return dir;
}

function stage(dir, file, contents) {
  writeFileSync(join(dir, file), contents);
  execFileSync('git', ['add', file], { cwd: dir, stdio: 'pipe' });
}

function runGate(dir) {
  try {
    const stdout = execFileSync('bash', [GATE_SCRIPT], { cwd: dir, stdio: 'pipe' }).toString();
    return { status: 0, stdout, stderr: '' };
  } catch (err) {
    return { status: err.status, stdout: err.stdout.toString(), stderr: err.stderr.toString() };
  }
}

test('an empty staged diff passes', () => {
  const dir = makeRepo();
  try {
    const result = runGate(dir);
    assert.equal(result.status, 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a merge conflict marker in the staged diff blocks the commit', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', '<<<<<<< HEAD\nconst a = 1;\n=======\nconst a = 2;\n>>>>>>> feature\n');
    const result = runGate(dir);
    assert.equal(result.status, 1);
    assert.match(result.stderr, /BLOCK.*merge-conflict-marker/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a debugger statement in a staged JS file blocks the commit', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', 'function f() {\n  debugger;\n  return 1;\n}\n');
    const result = runGate(dir);
    assert.equal(result.status, 1);
    assert.match(result.stderr, /BLOCK.*debugger-statement/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a focused test (.only) in a staged test file blocks the commit', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'test/foo.test.mjs', "import { test } from 'node:test';\ntest.only('x', () => {});\n");
    const result = runGate(dir);
    assert.equal(result.status, 1);
    assert.match(result.stderr, /BLOCK.*focused-test/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('.only outside of a test file is not treated as a focused test', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', "const picker = { only(x) { return x; } };\npicker.only(1);\n");
    const result = runGate(dir);
    assert.equal(result.status, 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a console.log statement is reported but does not block the commit', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', "function f() {\n  console.log('debugging');\n  return 1;\n}\n");
    const result = runGate(dir);
    assert.equal(result.status, 0);
    assert.match(result.stdout, /WARN.*console-debug/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a TODO comment is reported but does not block the commit', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', '// TODO: clean this up\nconst a = 1;\n');
    const result = runGate(dir);
    assert.equal(result.status, 0);
    assert.match(result.stdout, /WARN.*todo-comment/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('the override marker downgrades a blocking finding to a report on that line', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', 'function f() {\n  debugger; // quality-gate:allow\n  return 1;\n}\n');
    const result = runGate(dir);
    assert.equal(result.status, 0);
    assert.match(result.stdout, /WARN.*debugger-statement \(overridden\)/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('removed lines are not scanned for blocking patterns', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.mjs', 'debugger;\n');
    execFileSync('git', ['commit', '--quiet', '-m', 'add debugger'], { cwd: dir, stdio: 'pipe' });
    writeFileSync(join(dir, 'app.mjs'), 'const a = 1;\n');
    execFileSync('git', ['add', 'app.mjs'], { cwd: dir, stdio: 'pipe' });
    const result = runGate(dir);
    assert.equal(result.status, 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

